css:
body {
            font-family: 'Helvetica Neue', Arial, sans-serif;
            line-height: 1.6;
            color: #333;
            max-width: 800px;
            margin: 0 auto;
            padding: 20px;
        }
        .invoice-header {
            display: flex;
            justify-content: space-between;
            margin-bottom: 30px;
            border-bottom: 2px solid #eee;
            padding-bottom: 20px;
        }
        .left-column {
            width: 50%;
        }
        .right-column {
            width: 45%;
            text-align: right;
        }
        .uin {
            font-weight: bold;
            font-size: 16px;
            margin-bottom: 15px;
        }
        .bill-to {
            font-weight: bold;
            margin: 15px 0 5px 0;
        }
        .invoice-title {
            font-size: 24px;
            font-weight: bold;
            color: #2c3e50;
            margin-bottom: 10px;
        }
        .invoice-meta {
            margin-top: 10px;
        }
        .meta-item {
            margin-bottom: 5px;
        }
        .address {
            font-style: normal;
            line-height: 1.4;
        }
